 {"genre":"ninbo","diff":2,"era":"yayoi","q":"卑弥呼が神の意を聞くために用いたとされる、まじないのことを『魏志倭人伝』では何とよんでいますか。","c":["鬼道（きどう）","律令","御成敗式目","参勤交代"],"a":0,"desc":"卑弥呼のまじないは「鬼道」とよばれます。卑弥呼はこの宗教的な力で人々の心をつかみ、くにを束ねたとされています。"},
 {"genre":"ninbo","diff":3,"era":"yayoi","q":"卑弥呼の死後、再び乱れた倭をまとめるために女王となり、人々の心をふたたびひとつにした卑弥呼の一族の少女は誰ですか。","c":["壹与（いよ）","推古","額田王","和気広虫"],"a":0,"desc":"卑弥呼の死後、男王が立つと国が乱れたため、一族の少女・壹与（いよ）がわずか十三歳で女王となり、宗教的な権威で人心をまとめ、国はふたたび治まったとされます。"}
